/**
 * Activity photos PR 2 — upload, sanitising, review, consent, family viewing.
 * Real Express app over HTTP as app_runtime, a real S3-compatible PRIVATE
 * bucket (local moto server started here, never a hosted service) and ONLY
 * synthetic images generated by this script (with fake camera and GPS EXIF,
 * to prove they come out clean).
 *
 *   ETNARA_DISPOSABLE_DB=true MIGRATIONS_DATABASE_URL=postgres://<superuser>@<local>/<db>
 *   optional: PHOTO_TEST_S3_PORT (default 4568); requires `moto_server` on PATH.
 */
import { spawn, type ChildProcess } from "node:child_process";
import { randomBytes, randomUUID } from "node:crypto";
import type { AddressInfo } from "node:net";
import { CreateBucketCommand, ListObjectsV2Command, S3Client } from "@aws-sdk/client-s3";
import pg from "pg";
import sharp from "sharp";

const adminUrl = process.env.MIGRATIONS_DATABASE_URL;
if (!adminUrl || process.env.ETNARA_DISPOSABLE_DB !== "true") throw new Error("Requires MIGRATIONS_DATABASE_URL and ETNARA_DISPOSABLE_DB=true");
if (process.env.NODE_ENV === "production") throw new Error("Production prohibited");
if (/railway|rlwy|amazonaws|supabase|neon\.tech/i.test(adminUrl)) throw new Error("Hosted database refused");

type Json = Record<string, any>; // eslint-disable-line @typescript-eslint/no-explicit-any
const results: Array<{ check: string; pass: boolean; detail: string }> = [];
const check = (name: string, pass: boolean, detail = "") => results.push({ check: name, pass, detail });

// ---------------------------------------------------------------- synthetic images
async function syntheticJpeg(opts: { width?: number; height?: number; orientation?: number; gps?: boolean } = {}) {
  const width = opts.width ?? 1600, height = opts.height ?? 1200;
  const raw = Buffer.alloc(width * height * 3);
  for (let y = 0; y < height; y++) for (let x = 0; x < width; x++) {
    const i = (y * width + x) * 3; raw[i] = (x * 255) / width; raw[i + 1] = (y * 255) / height; raw[i + 2] = 128;
  }
  let img = sharp(raw, { raw: { width, height, channels: 3 } }).jpeg({ quality: 90 });
  const exif: Record<string, Record<string, string>> = {
    IFD0: { Make: "SyntheticCam", Model: "FakeModel-ETNARA", Software: "synthetic-test", Artist: "Persona Sintetica" },
  };
  if (opts.gps !== false) exif.IFD3 = { GPSLatitudeRef: "N", GPSLatitude: "18/1 27/1 3000/100", GPSLongitudeRef: "W", GPSLongitude: "66/1 6/1 1500/100" };
  img = img.withExif(exif);
  if (opts.orientation) img = img.withMetadata({ orientation: opts.orientation });
  return img.toBuffer();
}

async function main() {
  // Local private S3 (moto). Nothing leaves this machine.
  const s3Port = Number(process.env.PHOTO_TEST_S3_PORT ?? 4568);
  const moto: ChildProcess = spawn("moto_server", ["-H", "127.0.0.1", "-p", String(s3Port)], { stdio: "ignore" });
  const endpoint = `http://127.0.0.1:${s3Port}`;
  for (let i = 0; i < 60; i++) { try { await fetch(endpoint); break; } catch { await new Promise((r) => setTimeout(r, 250)); } }
  const bucket = `etnara-photos-test-${randomBytes(4).toString("hex")}`;
  const s3 = new S3Client({ endpoint, region: "us-east-1", forcePathStyle: true, credentials: { accessKeyId: "test", secretAccessKey: "test" } });
  await s3.send(new CreateBucketCommand({ Bucket: bucket }));
  Object.assign(process.env, {
    PHOTO_STORAGE_ENDPOINT: endpoint, PHOTO_STORAGE_REGION: "us-east-1", PHOTO_STORAGE_BUCKET: bucket,
    PHOTO_STORAGE_ACCESS_KEY_ID: "test", PHOTO_STORAGE_SECRET_ACCESS_KEY: "test", PHOTO_STORAGE_FORCE_PATH_STYLE: "true",
    PHOTO_MAX_UPLOAD_BYTES: String(6 * 1024 * 1024),
  });
  delete process.env.STORAGE_ENDPOINT; delete process.env.STORAGE_BUCKET;
  const objects = async (prefix: string) => (await s3.send(new ListObjectsV2Command({ Bucket: bucket, Prefix: prefix }))).KeyCount ?? 0;

  const db = new pg.Client({ connectionString: adminUrl });
  await db.connect();
  const q = <T extends pg.QueryResultRow = pg.QueryResultRow>(s: string, p: unknown[] = []) => db.query<T>(s, p);
  const runtimePassword = randomBytes(24).toString("hex");
  await q(`ALTER ROLE app_runtime WITH LOGIN PASSWORD '${runtimePassword}'`);
  const u = new URL(adminUrl!); u.username = "app_runtime"; u.password = runtimePassword;
  process.env.DATABASE_URL = u.toString();

  // Capture everything the server writes to the error log during the run.
  const logged: string[] = [];
  const origError = console.error;
  console.error = (...args: unknown[]) => { logged.push(args.map((a) => (typeof a === "string" ? a : JSON.stringify(a))).join(" ")); };

  const { hashPassword } = await import("../src/security/password.js");
  const { createApp } = await import("../src/app.js");
  const { pool } = await import("../src/config/db.js");
  const server = createApp().listen(0);
  await new Promise((r) => server.once("listening", r));
  const base = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
  const password = randomBytes(18).toString("hex");
  const hash = await hashPassword(password);
  const tag = randomUUID().slice(0, 8);
  const bodies: string[] = [];

  async function call(method: string, path: string, token: string, body?: Json | Buffer, contentType?: string) {
    const isBuf = Buffer.isBuffer(body);
    const res = await fetch(base + path, {
      method,
      headers: { ...(token ? { Authorization: `Bearer ${token}` } : {}), ...(body !== undefined ? { "Content-Type": contentType ?? (isBuf ? "image/jpeg" : "application/json") } : {}) },
      body: body === undefined ? undefined : isBuf ? new Uint8Array(body as Buffer) : JSON.stringify(body),
    });
    const buf = Buffer.from(await res.arrayBuffer());
    const ct = res.headers.get("content-type") ?? "";
    let json: Json = {};
    if (ct.includes("application/json")) { try { json = JSON.parse(buf.toString("utf8")); } catch { /* ignore */ } bodies.push(buf.toString("utf8")); }
    return { status: res.status, body: json, bytes: buf, headers: res.headers };
  }

  // ---------------------------------------------------------------- fixtures
  const org = async (name: string) => (await q<{ id: string }>(`INSERT INTO organizations (name,organization_type,status) VALUES ($1,'HOME_CARE_AGENCY','active') RETURNING id`, [name])).rows[0].id;
  const orgA = await org(`PH2 A ${tag}`);
  const orgB = await org(`PH2 B ${tag}`);
  const bls = (await q<{ id: string }>(`SELECT id FROM credential_types WHERE code='BLS'`)).rows[0].id;
  const noteType = (await q<{ id: string }>(`SELECT id FROM care_event_types WHERE code='NOTE'`)).rows[0].id;
  type P = { email: string; userId: string; token: string; owm?: string };
  async function person(key: string, orgId: string, roles: string[], worker = false): Promise<P> {
    const email = `ph2-${key}-${tag}@example.invalid`;
    const userId = (await q<{ id: string }>(`INSERT INTO users (email,password_hash,status) VALUES ($1,$2,'active') RETURNING id`, [email, hash])).rows[0].id;
    const m = (await q<{ id: string }>(`INSERT INTO organization_memberships (user_id,organization_id,status) VALUES ($1,$2,'active') RETURNING id`, [userId, orgId])).rows[0].id;
    await q(`INSERT INTO user_roles (organization_membership_id,organization_id,role_id) SELECT $1,$2,id FROM roles WHERE code = ANY($3)`, [m, orgId, roles]);
    let owm: string | undefined;
    if (worker) {
      const workerId = (await q<{ id: string }>(`INSERT INTO workers (user_id,display_name) VALUES ($1,$2) RETURNING id`, [userId, `Synthetic ${key}`])).rows[0].id;
      owm = (await q<{ id: string }>(`INSERT INTO organization_worker_memberships (worker_id,organization_id,status,internal_role) VALUES ($1,$2,'active','caregiver') RETURNING id`, [workerId, orgId])).rows[0].id;
      await q(`INSERT INTO credentials (worker_id,credential_type_id,issuing_entity_type,status,expires_at) VALUES ($1,$2,'external_provider','active',current_date+365)`, [workerId, bls]);
    }
    return { email, userId, token: "", owm };
  }
  const A = {
    admin: await person("a-admin", orgA, ["ORGANIZATION_ADMIN"]), admin2: await person("a-admin2", orgA, ["ORGANIZATION_ADMIN"]),
    sup: await person("a-sup", orgA, ["SUPERVISOR"]),
    cg1: await person("a-cg1", orgA, ["WORKER"], true), cg2: await person("a-cg2", orgA, ["WORKER"], true),
    fam1: await person("a-fam1", orgA, ["FAMILY"]), famNoPhotos: await person("a-famnp", orgA, ["FAMILY"]), fam2: await person("a-fam2", orgA, ["FAMILY"]),
  };
  const B = { admin: await person("b-admin", orgB, ["ORGANIZATION_ADMIN"]), cg: await person("b-cg", orgB, ["WORKER"], true) };
  const recipient = async (o: string) => (await q<{ id: string }>(`INSERT INTO care_recipients (organization_id,first_name,last_name,status) VALUES ($1,'Sintetico',$2,'active') RETURNING id`, [o, `R-${tag}`])).rows[0].id;
  const r1 = await recipient(orgA), r2 = await recipient(orgA), rB = await recipient(orgB);
  await q(`INSERT INTO family_relationships (user_id,organization_id,care_recipient_id,relationship_type,status,can_view_photos) VALUES
    ($1,$4,$5,'hija','active',true), ($2,$4,$5,'hijo','active',false), ($3,$4,$6,'hija','active',true)`, [A.fam1.userId, A.famNoPhotos.userId, A.fam2.userId, orgA, r1, r2]);
  async function shiftFor(o: string, rec: string, owm: string) {
    const s = (await q<{ id: string }>(`INSERT INTO shifts (organization_id,care_recipient_id,scheduled_start,scheduled_end,status) VALUES ($1,$2,now()-interval '1 hour',now()+interval '3 hours','in_progress') RETURNING id`, [o, rec])).rows[0].id;
    await q(`INSERT INTO assignments (organization_id,shift_id,organization_worker_membership_id,response_status,responded_at) VALUES ($1,$2,$3,'accepted',now())`, [o, s, owm]);
    return s;
  }
  const sA1 = await shiftFor(orgA, r1, A.cg1.owm!), sA2 = await shiftFor(orgA, r2, A.cg2.owm!), sB = await shiftFor(orgB, rB, B.cg.owm!);
  const activity = async (o: string, shift: string, rec: string, owm: string, ageHours = 0) =>
    (await q<{ id: string }>(`INSERT INTO care_events (organization_id,shift_id,care_recipient_id,organization_worker_membership_id,care_event_type_id,note_text,occurred_at,created_at)
      VALUES ($1,$2,$3,$4,$5,'Paseo sintetico',now()-make_interval(hours=>$6::int),now()-make_interval(hours=>$6::int)) RETURNING id`, [o, shift, rec, owm, noteType, ageHours])).rows[0].id;
  const ev = { a: await activity(orgA, sA1, r1, A.cg1.owm!), b: await activity(orgA, sA1, r1, A.cg1.owm!), c: await activity(orgA, sA1, r1, A.cg1.owm!),
    d: await activity(orgA, sA1, r1, A.cg1.owm!), race: await activity(orgA, sA1, r1, A.cg1.owm!), old: await activity(orgA, sA1, r1, A.cg1.owm!, 13),
    r2: await activity(orgA, sA2, r2, A.cg2.owm!), bEv: await activity(orgB, sB, rB, B.cg.owm!) };
  for (const p of [...Object.values(A), ...Object.values(B)]) {
    const r = await call("POST", "/auth/login", "", { email: p.email, password });
    if (r.status !== 200) throw new Error(`login ${p.email} ${r.status}`);
    p.token = r.body.token;
    await call("POST", "/me/active-organization", p.token, { organizationId: p === B.admin || p === B.cg ? orgB : orgA });
  }
  const O = `/organizations/${orgA}`;
  const upload = (who: P, eventId: string, img: Buffer, ct = "image/jpeg", o = orgA) => call("POST", `/organizations/${o}/care-events/${eventId}/photo`, who.token, img, ct);
  const image = (who: P, photoId: string, o = orgA) => call("GET", `/organizations/${o}/activity-photos/${photoId}/image`, who.token);
  const statusOf = async (photoId: string) => (await q<{ s: string }>(`SELECT share_status s FROM care_event_photos WHERE id=$1`, [photoId])).rows[0]?.s ?? "pending";
  const review = async (who: P, photoId: string, decision: string, reason?: string, expectedStatus?: string) =>
    call("POST", `${O}/activity-photos/${photoId}/review`, who.token, { decision, expectedStatus: expectedStatus ?? await statusOf(photoId), ...(reason ? { reason } : {}) });
  const consentForm = async () => sharp({ create: { width: 400, height: 500, channels: 3, background: "#eeeeee" } }).jpeg().withExif({ IFD0: { Artist: "Firma Sintetica" } }).toBuffer();
  const addConsent = async (who: P, rec: string, type: string, body?: Buffer, ct = "image/jpeg") =>
    call("POST", `${O}/care-recipients/${rec}/photo-consents?type=${type}&signerRole=LEGAL_REPRESENTATIVE`, who.token, body ?? await consentForm(), ct);
  const enable = (o: string, on: boolean) => q(`INSERT INTO organization_features (organization_id,feature_code,enabled) VALUES ($1,'ACTIVITY_PHOTOS',$2)
    ON CONFLICT (organization_id,feature_code) DO UPDATE SET enabled = EXCLUDED.enabled`, [o, on]);
  const jpeg = await syntheticJpeg();

  try {
    // ---------------------------------------------------------------- switch
    const offUp = await upload(A.cg1, ev.a, jpeg);
    const offList = await call("GET", `${O}/activity-photos`, A.admin.token);
    const offConsent = await addConsent(A.admin, r1, "PHOTO_CAPTURE");
    check("S1 ACTIVITY_PHOTOS off (default): every photo route answers 404 FEATURE_NOT_ENABLED and nothing is stored",
      [offUp, offList, offConsent].every((r) => r.status === 404 && r.body.error === "FEATURE_NOT_ENABLED") && (await objects("")) === 0,
      `${offUp.status} ${offList.status} ${offConsent.status} objects=${await objects("")}`);
    await enable(orgA, true); await enable(orgB, true);

    // ---------------------------------------------------------------- consent
    const noConsent = await upload(A.cg1, ev.a, jpeg);
    check("C1 upload refused without the resident's capture consent (409), before any byte is stored",
      noConsent.status === 409 && noConsent.body.error === "PHOTO_CONSENT_REQUIRED" && (await objects("")) === 0, `${noConsent.status} ${noConsent.body.error}`);
    const cgConsent = await addConsent(A.cg1, r1, "PHOTO_CAPTURE");
    const famConsent = await addConsent(A.fam1, r1, "PHOTO_CAPTURE");
    const noForm = await call("POST", `${O}/care-recipients/${r1}/photo-consents?type=PHOTO_CAPTURE&signerRole=PATIENT`, A.admin.token, Buffer.alloc(0), "application/pdf");
    const textForm = await addConsent(A.admin, r1, "PHOTO_CAPTURE", Buffer.from("no soy un pdf"), "application/pdf");
    check("C2 consents: only managers (caregiver/relative 403); the signed form is required and must really be a PDF or image",
      cgConsent.status === 403 && famConsent.status === 403 && noForm.status === 400 && textForm.status === 415 && (await objects("photo-consent-forms/")) === 0,
      `${cgConsent.status} ${famConsent.status} ${noForm.status} ${textForm.status}`);
    const cap = await addConsent(A.sup, r1, "PHOTO_CAPTURE");
    const pdf = Buffer.concat([Buffer.from("%PDF-1.4\n% formulario sintetico\n"), randomBytes(200), Buffer.from("\n%%EOF")]);
    const share = await addConsent(A.admin, r1, "PHOTO_SHARE_FAMILY", pdf, "application/pdf");
    await addConsent(A.admin, r2, "PHOTO_CAPTURE");
    const formBack = await call("GET", `${O}/photo-consents/${cap.body.consent?.id}/form`, A.admin.token);
    const formCg = await call("GET", `${O}/photo-consents/${cap.body.consent?.id}/form`, A.cg1.token);
    const formMeta = formBack.status === 200 ? await sharp(formBack.bytes).metadata() : null;
    check("C3 a supervisor records the capture consent with an image form, an admin the sharing one with a PDF; the form is served to managers only (others 404), without metadata",
      cap.status === 201 && share.status === 201 && formBack.status === 200 && !formMeta?.exif && formCg.status === 404 && (await objects("photo-consent-forms/")) === 3,
      `${cap.status} ${share.status} ${formBack.status} exif=${Boolean(formMeta?.exif)} cg=${formCg.status}`);
    const consents = await call("GET", `${O}/care-recipients/${r1}/photo-consents`, A.admin.token);
    check("C4 the consent list shows type, version, signer and who recorded it, without file ids or keys",
      consents.status === 200 && consents.body.consents.length === 2 && !JSON.stringify(consents.body).match(/photo-consent-forms|signed_form|fileId/i), JSON.stringify(consents.body.consents?.map((c: Json) => c.type)));

    // ---------------------------------------------------------------- upload + sanitising
    const inMeta = await sharp(jpeg).metadata();
    const up = await upload(A.cg1, ev.a, jpeg);
    const photoId = up.body.photo?.id as string;
    check("U1 the caregiver uploads one photo for her activity: 201, «pending», resized to ≤ 2048 px",
      up.status === 201 && up.body.photo?.status === "pending" && Math.max(up.body.photo?.width ?? 0, up.body.photo?.height ?? 0) <= 2048, JSON.stringify(up.body));
    const own = await image(A.cg1, photoId);
    const outMeta = own.status === 200 ? await sharp(own.bytes).metadata() : null;
    const raw = own.bytes.toString("latin1");
    check("U2 EXIF removed on the server: the input had camera + GPS, the stored image has no EXIF/XMP/ICC, no GPS, no camera strings, no APP1 segment",
      !!inMeta.exif && outMeta !== null && !outMeta.exif && !outMeta.xmp && !outMeta.icc && !raw.includes("SyntheticCam") && !raw.includes("FakeModel")
        && !raw.includes("Persona Sintetica") && !raw.includes("Exif\0\0") && !own.bytes.includes(Buffer.from([0xff, 0xe1])),
      `in.exif=${Boolean(inMeta.exif)} out.exif=${Boolean(outMeta?.exif)} format=${outMeta?.format}`);
    const rotated = await upload(A.cg1, ev.b, await syntheticJpeg({ width: 800, height: 400, orientation: 6, gps: true }));
    const rotImg = await image(A.cg1, rotated.body.photo?.id);
    const rotMeta = await sharp(rotImg.bytes).metadata();
    check("U3 orientation is applied to the pixels before the tag is dropped (800×400 tagged «rotate 90°» → 400×800, no orientation tag)",
      rotated.status === 201 && rotMeta.width === 400 && rotMeta.height === 800 && !rotMeta.orientation, `${rotated.status} ${rotMeta.width}x${rotMeta.height} o=${rotMeta.orientation}`);
    const png = await upload(A.cg1, ev.c, await sharp(jpeg).png().toBuffer(), "image/png");
    const webp = await upload(A.cg1, ev.d, await sharp(jpeg).webp().toBuffer(), "image/webp");
    check("U4 PNG and WebP are accepted and stored as clean JPEG", png.status === 201 && webp.status === 201, `${png.status} ${webp.status}`);
    const heic = Buffer.concat([Buffer.from([0, 0, 0, 0x18]), Buffer.from("ftypheic"), randomBytes(64)]);
    const bad = {
      heic: await upload(A.cg1, ev.race, heic, "image/heic"),
      text: await upload(A.cg1, ev.race, Buffer.from("<script>alert(1)</script>"), "image/jpeg"),
      truncated: await upload(A.cg1, ev.race, jpeg.subarray(0, 300), "image/jpeg"),
      empty: await upload(A.cg1, ev.race, Buffer.alloc(0), "image/jpeg"),
      huge: await upload(A.cg1, ev.race, Buffer.concat([jpeg, randomBytes(7 * 1024 * 1024)]), "image/jpeg"),
      svg: await upload(A.cg1, ev.race, Buffer.from("<svg xmlns='http://www.w3.org/2000/svg'/>"), "image/svg+xml"),
    };
    check("U5 rejected by content, not by declared type: HEIC 415, script-as-jpeg 415, truncated 422, empty 400, too large 413, SVG 415 — and nothing left in the bucket",
      bad.heic.status === 415 && bad.heic.body.error === "PHOTO_HEIC_NOT_SUPPORTED" && bad.text.status === 415 && bad.truncated.status === 422
        && bad.empty.status === 400 && bad.huge.status === 413 && bad.svg.status === 415 && (await objects(`activity-photos/${orgA}/${r1}/`)) === 4,
      Object.entries(bad).map(([k, v]) => `${k}=${v.status}`).join(" ") + ` objects=${await objects(`activity-photos/${orgA}/${r1}/`)}`);

    // ---------------------------------------------------------------- id tampering and isolation
    const tamper = {
      second: await upload(A.cg1, ev.a, jpeg),
      othersActivity: await upload(A.cg1, ev.r2, jpeg),
      oldActivity: await upload(A.cg1, ev.old, jpeg),
      otherAgencyEvent: await upload(A.cg1, ev.bEv, jpeg),
      otherAgencyPath: await upload(A.cg1, ev.bEv, jpeg, "image/jpeg", orgB),
      relative: await upload(A.fam1, ev.race, jpeg),
      manager: await upload(A.admin, ev.race, jpeg),
      unknownId: await upload(A.cg1, randomUUID(), jpeg),
    };
    check("T1 one photo per activity (409); another caregiver's, an old, another agency's or an unknown activity → 404 (403 for a foreign agency path); relatives and managers cannot upload (404, nothing revealed)",
      tamper.second.status === 409 && tamper.othersActivity.status === 404 && tamper.oldActivity.status === 404 && tamper.otherAgencyEvent.status === 404
        && tamper.otherAgencyPath.status === 403 && tamper.relative.status === 404 && tamper.manager.status === 404 && tamper.unknownId.status === 404,
      Object.entries(tamper).map(([k, v]) => `${k}=${v.status}:${v.body.error}`).join(" "));
    const views = {
      cg2: await image(A.cg2, photoId), fam1Pending: await image(A.fam1, photoId), admin: await image(A.admin, photoId),
      adminBpath: await image(B.admin, photoId, orgB), adminBforeign: await image(B.admin, photoId), random: await image(A.admin, randomUUID()),
    };
    check("T2 pending photo: the agency sees it, another caregiver and the relative do not (404), another agency neither through its own path nor ours",
      views.admin.status === 200 && views.cg2.status === 404 && views.fam1Pending.status === 404 && views.adminBpath.status === 404
        && views.adminBforeign.status === 403 && views.random.status === 404,
      Object.entries(views).map(([k, v]) => `${k}=${v.status}`).join(" "));
    const listByCg = await call("GET", `${O}/activity-photos`, A.cg1.token);
    const listByFam = await call("GET", `${O}/activity-photos`, A.fam1.token);
    const listB = await call("GET", `/organizations/${orgB}/activity-photos`, B.admin.token);
    check("T3 the review queue is for the agency's managers only; another agency sees none of ours",
      listByCg.status === 403 && listByFam.status === 403 && listB.status === 200 && listB.body.photos.length === 0, `${listByCg.status} ${listByFam.status} B=${listB.body.photos?.length}`);

    // ---------------------------------------------------------------- review → family
    const queue = await call("GET", `${O}/activity-photos?status=pending`, A.admin.token);
    check("R1 the agency queue lists the 4 pending photos with resident, activity and caregiver", queue.status === 200 && queue.body.photos.length === 4,
      `${queue.status} ${queue.body.photos?.length}`);
    const byCg = await review(A.cg1, photoId, "APPROVE");
    const noReason = await review(A.admin, photoId, "REJECT");
    const approve = await review(A.sup, photoId, "APPROVE");
    const famSees = await image(A.fam1, photoId);
    const others = { noPhotos: await image(A.famNoPhotos, photoId), fam2: await image(A.fam2, photoId) };
    check("R2 only managers review (caregiver 403), a reason is needed to reject; once approved the relative of THAT resident gets the image, nobody else",
      byCg.status === 403 && noReason.status === 400 && approve.status === 200 && famSees.status === 200 && others.noPhotos.status === 404 && others.fam2.status === 404,
      `${byCg.status} ${noReason.status} ${approve.status} fam=${famSees.status} noPhotos=${others.noPhotos.status} fam2=${others.fam2.status}`);
    check("R3 the image response is private: no-store, nosniff, sandboxed, JPEG, no storage path in headers",
      famSees.headers.get("cache-control")?.includes("no-store") === true && famSees.headers.get("x-content-type-options") === "nosniff"
        && famSees.headers.get("content-type") === "image/jpeg" && (famSees.headers.get("content-security-policy") ?? "").includes("sandbox")
        && ![...famSees.headers.values()].some((v) => v.includes(bucket) || v.includes("activity-photos/")),
      `${famSees.headers.get("cache-control")} ${famSees.headers.get("content-type")}`);
    const tl = await call("GET", `${O}/care-recipients/${r1}/timeline`, A.fam1.token);
    const withPhoto = (tl.body.items as Json[] ?? []).filter((i) => i.photo?.visible);
    check("R4 the family timeline marks only the approved photo (on a NOTE activity) with its reference", tl.status === 200 && withPhoto.length === 1 && withPhoto[0].photo.reference === photoId,
      `${tl.status} ${withPhoto.length}`);

    // ---------------------------------------------------------------- immediate blocking
    const block: Record<string, number> = {};
    await review(A.admin, photoId, "WITHDRAW", "Retirada por la agencia"); block.withdrawn = (await image(A.fam1, photoId)).status;
    await review(A.admin, photoId, "APPROVE"); block.reapproved = (await image(A.fam1, photoId)).status;
    await q(`UPDATE family_relationships SET can_view_photos=false WHERE user_id=$1`, [A.fam1.userId]); block.noPermission = (await image(A.fam1, photoId)).status;
    await q(`UPDATE family_relationships SET can_view_photos=true, status='revoked' WHERE user_id=$1`, [A.fam1.userId]); block.relationshipRevoked = (await image(A.fam1, photoId)).status;
    await q(`UPDATE family_relationships SET status='active' WHERE user_id=$1`, [A.fam1.userId]);
    await enable(orgA, false); block.switchOff = (await image(A.fam1, photoId)).status; await enable(orgA, true);
    block.back = (await image(A.fam1, photoId)).status;
    const revokeByCg = await call("POST", `${O}/photo-consents/${share.body.consent.id}/revoke`, A.cg1.token, { reason: "Intento de cuidadora" });
    const revoke = await call("POST", `${O}/photo-consents/${share.body.consent.id}/revoke`, A.admin.token, { reason: "Revoca la representante" });
    block.consentRevoked = (await image(A.fam1, photoId)).status;
    await addConsent(A.admin, r1, "PHOTO_SHARE_FAMILY");
    block.newConsentNoReapproval = (await image(A.fam1, photoId)).status;
    check("B1 the relative is blocked at once when the approval is withdrawn, photo permission removed, relationship revoked, switch off or sharing consent revoked; a new consent needs re-approval",
      block.withdrawn === 404 && block.reapproved === 200 && block.noPermission === 404 && block.relationshipRevoked === 404 && block.switchOff === 404
        && block.back === 200 && revokeByCg.status === 403 && revoke.status === 200 && block.consentRevoked === 404 && block.newConsentNoReapproval === 404,
      JSON.stringify(block) + ` revokeByCg=${revokeByCg.status}`);
    await review(A.admin, photoId, "WITHDRAW", "Revision tras nuevo consentimiento");
    await review(A.admin, photoId, "APPROVE");

    // ---------------------------------------------------------------- concurrency
    const raceImg = await syntheticJpeg({ width: 900, height: 700 });
    const raceUp = await Promise.all([1, 2, 3, 4].map(() => upload(A.cg1, ev.race, raceImg)));
    await new Promise((r) => setTimeout(r, 300));
    const raceObjs = await objects(`activity-photos/${orgA}/${r1}/`);
    check("K1 four simultaneous uploads for one activity: exactly one 201, the rest 409, no orphan object left in the bucket",
      raceUp.filter((r) => r.status === 201).length === 1 && raceUp.filter((r) => r.status === 409).length === 3 && raceObjs === 5,
      `${raceUp.map((r) => r.status).join(",")} objects=${raceObjs}`);
    const racePhoto = raceUp.find((r) => r.status === 201)!.body.photo.id as string;
    // Both managers are looking at the same «pending» photo.
    const dual = await Promise.all([review(A.admin, racePhoto, "APPROVE", undefined, "pending"), review(A.admin2, racePhoto, "REJECT", "Rechazo simultaneo", "pending")]);
    const raceState = (await q(`SELECT share_status FROM care_event_photos WHERE id=$1`, [racePhoto])).rows[0].share_status;
    const stale = await review(A.admin, racePhoto, "WITHDRAW", "Vista desactualizada", "pending");
    const raceHist = Number((await q(`SELECT count(*) n FROM care_event_photo_events WHERE photo_id=$1`, [racePhoto])).rows[0].n);
    check("K2 two managers decide on the same «pending» photo at once: one wins, the other gets 409 PHOTO_STATUS_CHANGED (no silent override); a decision on a stale view is refused",
      dual.filter((r) => r.status === 200).length === 1 && dual.filter((r) => r.status === 409 && r.body.error === "PHOTO_STATUS_CHANGED").length === 1
        && ["approved", "rejected"].includes(raceState) && raceHist === 2 && stale.status === 409,
      `${dual.map((r) => `${r.status}:${r.body.error ?? ""}`).join(",")} ${raceState} history=${raceHist} stale=${stale.status}`);
    const viewsDuring = await Promise.all([
      ...[1, 2, 3, 4, 5].map(() => image(A.fam1, photoId)),
      call("POST", `${O}/photo-consents/${(await call("GET", `${O}/care-recipients/${r1}/photo-consents`, A.admin.token)).body.consents.find((c: Json) => c.type === "PHOTO_SHARE_FAMILY" && c.active).id}/revoke`, A.admin.token, { reason: "Revocacion concurrente" }),
    ]);
    const after = await Promise.all([1, 2, 3].map(() => image(A.fam1, photoId)));
    check("K3 views racing a consent revocation: each one is either the image or 404 (never an error), and every view after the revocation is 404",
      viewsDuring.slice(0, 5).every((r) => r.status === 200 || r.status === 404) && viewsDuring[5].status === 200 && after.every((r) => r.status === 404),
      `${viewsDuring.map((r) => r.status).join(",")} after=${after.map((r) => r.status).join(",")}`);

    // ---------------------------------------------------------------- audit and leaks
    const hist = await call("GET", `${O}/activity-photos/${photoId}/history`, A.admin.token);
    const histCg = await call("GET", `${O}/activity-photos/${photoId}/history`, A.cg1.token);
    const audit = (await q<{ action: string; n: string }>(`SELECT action, count(*) n FROM audit_log WHERE organization_id=$1 AND action IN
      ('ACTIVITY_PHOTO_UPLOADED','PHOTO_CONSENT_RECORDED','PHOTO_CONSENT_REVOKED') GROUP BY action`, [orgA])).rows;
    const access = (await q<{ viewer_kind: string; views: number }>(`SELECT viewer_kind, views FROM care_event_photo_access_log WHERE photo_id=$1`, [photoId])).rows;
    check("A1 audited: history (managers only), uploads, consents recorded and revoked; relatives' views logged once per day with a counter",
      hist.status === 200 && hist.body.history.length >= 6 && histCg.status === 403 && audit.length === 3
        && access.length === 1 && access[0].viewer_kind === "FAMILY" && access[0].views >= 4,
      `hist=${hist.body.history?.length} cg=${histCg.status} audit=${JSON.stringify(audit)} access=${JSON.stringify(access)}`);
    const keyLeak = bodies.some((b) => b.includes("activity-photos/") || b.includes("photo-consent-forms/") || b.includes(bucket) || b.includes("storage_key"));
    const fileIds = (await q<{ id: string }>(`SELECT file_id AS id FROM care_event_photos WHERE organization_id=$1`, [orgA])).rows.map((r) => r.id);
    const idLeak = bodies.some((b) => fileIds.some((id) => b.includes(id)));
    const logLeak = logged.some((l) => l.includes("activity-photos/") || l.includes(bucket) || l.includes("SyntheticCam") || fileIds.some((id) => l.includes(id)));
    check("A2 no JSON response and no log line contains a storage key, bucket name, file id or image content", !keyLeak && !idLeak && !logLeak,
      `responses=${keyLeak || idLeak} logs=${logLeak} (${logged.length} log lines)`);
    const notes = Number((await q(`SELECT count(*) n FROM notifications WHERE organization_id=$1 AND (notification_type ILIKE '%PHOTO%')`, [orgA])).rows[0].n);
    check("A3 no notification carries photos (none is sent by these flows)", notes === 0, String(notes));
  } finally {
    console.error = origError;
    server.close();
    await pool.end().catch(() => undefined);
    await db.end();
    moto.kill();
  }

  console.log("\nActivity photos · upload, sanitising, review, consent, family (PR 2)\n");
  console.log("| Check | Result | Detail |\n|---|---|---|");
  for (const r of results) console.log(`| ${r.check} | ${r.pass ? "PASS" : "FAIL"} | ${r.detail} |`);
  const failed = results.filter((r) => !r.pass).length;
  console.log(`\nActivity photo upload: ${results.length - failed}/${results.length} PASS`);
  if (failed) process.exit(1);
}

main().catch((error) => {
  console.error("Activity photo upload verification failed:", error);
  process.exit(1);
});
